import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int m = nextInt(), n = nextInt();
        // prefix[i]: clockwise distance from hub 1 to hub i + 1.
        long[] prefix = new long[m + 1];
        for (int i = 0; i < m; i++) prefix[i + 1] = prefix[i] + nextLong();
        long answer = 0;
        int previous = 0;
        for (int i = 0; i < n; i++) {
            int current = nextInt() - 1;
            long distance = Math.abs(prefix[current] - prefix[previous]);
            answer += Math.min(distance, prefix[m] - distance);
            previous = current;
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	m, n := nextInt(), nextInt()
	// prefix[i]: clockwise distance from hub 1 to hub i + 1.
	prefix := make([]int, m+1)
	for i := 0; i < m; i++ {
		prefix[i+1] = prefix[i] + nextInt()
	}
	answer, previous := 0, 0
	for i := 0; i < n; i++ {
		current := nextInt() - 1
		distance := prefix[current] - prefix[previous]
		if distance < 0 {
			distance = -distance
		}
		answer += min(distance, prefix[m]-distance)
		previous = current
	}
	fmt.Println(answer)
}
